(()=>{
 const finished=ticket=>['completed','cancelled','declined'].includes(ticket.status);
 const date=value=>value?new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'—';
 const back=(label,target='home')=>`<button class="back" id="panel-back" data-target="${target}">← ${label}</button>`;
 const bindBack=()=>{document.querySelector('#panel-back').onclick=e=>{view=e.currentTarget.dataset.target;selected=null;render();};};
 const assignedName=ticket=>data.technicians.find(x=>x.id===ticket.technicianId)?.name||'Not assigned';
 const activity=ticket=>(ticket.history||[]).map((entry,index)=>`<li><span class="timeline-dot"></span><div><strong>${esc(labels[entry.status]||entry.status||'Updated')}</strong><small>${esc(date(entry.at))}${entry.paymentStatus?' · Payment: '+esc(entry.paymentStatus):''}</small></div></li>`).join('');
 function branches(){const rows=(data.settings.branches||[]).map(x=>`${x.name}|${x.latitude}|${x.longitude}`).join('\n');app.innerHTML=`${back('Owner dashboard')}<section class="card focus-panel"><div class="eyebrow">OWNER TOOLS</div><h1>Service branches</h1><p class="muted">Only these branches appear to customers. One per line: Branch name | latitude | longitude.</p><form id="focused-branches"><label class="field">Branches<textarea name="branches" required>${esc(rows)}</textarea></label><button class="primary">Save branches</button></form></section>`;bindBack();document.querySelector('#focused-branches').onsubmit=e=>{e.preventDefault();const list=new FormData(e.target).get('branches').split('\n').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x.length===3&&x[0]).map(([name,latitude,longitude])=>({id:name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),name,latitude:Number(latitude),longitude:Number(longitude)}));act('settings',{...data.settings,areas:data.settings.areas,branches:list});};}
 function detail(){const ticket=data.bookings.find(x=>x.id===selected);if(!ticket){view='tickets';render();return;}const techs=(data.technicians||[]).filter(x=>x.skills.includes(ticket.service));app.innerHTML=`${back('All tickets','tickets')}<div class="intro"><div><div class="eyebrow">TICKET ${esc(ticket.id)}</div><h1>${esc(svc(ticket.service).en)}</h1><p>Created ${esc(date(ticket.createdAt))}</p></div><span class="pill">${esc(status(ticket))}</span></div><div class="layout ticket-detail-layout"><section><div class="card"><h2>Request details</h2><div class="ticket-facts"><p><b>Customer</b><span>${esc(ticket.name)} · ${esc(ticket.phone)}</span></p><p><b>Service</b><span>${esc(svc(ticket.service).en)}</span></p><p><b>Problem</b><span>${esc(ticket.issue)}</span></p><p><b>Visit window</b><span>${esc(ticket.slot)}</span></p><p><b>Village and PIN</b><span>${esc(ticket.village)} · ${esc(ticket.pin)}</span></p><p><b>Landmark</b><span>${esc(ticket.landmark)}</span></p><p><b>Technician</b><span>${esc(assignedName(ticket))}</span></p></div></div><div class="card"><h2>Ticket tracking</h2><ol class="ticket-history">${activity(ticket)}</ol></div></section><aside><div class="card"><h2>Cost and payment</h2><div class="line"><span>Visit fee</span><strong>${money(ticket.fees?.visit||0)}</strong></div><div class="line"><span>Travel fee</span><strong>${money(ticket.fees?.travel||0)}</strong></div>${ticket.estimate?`<div class="divider"></div><p>${esc(ticket.estimate.description)}</p><div class="line"><span>Labour</span><strong>${money(ticket.estimate.labor)}</strong></div><div class="line"><span>Parts</span><strong>${money(ticket.estimate.parts)}</strong></div><div class="line"><span>Estimate total</span><strong>${money(ticket.estimate.total)}</strong></div>`:'<p class="muted">No repair estimate yet.</p>'}<p><b>Payment:</b> ${esc(ticket.paymentStatus||'unpaid')}${ticket.receipt?' · '+esc(ticket.receipt):''}</p>${ticket.notes?`<p><b>Completion notes</b><br>${esc(ticket.notes)}</p>`:''}${ticket.rating?`<p><b>Customer rating:</b> ${ticket.rating} / 5</p>`:''}</div><div class="card"><h2>Admin actions</h2>${['requested','assigned'].includes(ticket.status)?`<label class="field">${ticket.technicianId?'Reassign technician':'Assign technician'}<select id="detail-tech">${techs.map(x=>`<option value="${x.id}" ${x.id===ticket.technicianId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="primary full" id="detail-assign" ${techs.length?'':'disabled'}>${ticket.technicianId?'Save reassignment':'Save assignment'}</button>`:''}${!finished(ticket)?'<button class="danger full" id="close-ticket">Close ticket</button>':'<p class="muted">No further actions are available for this ticket.</p>'}</div></aside></div>`;bindBack();document.querySelector('#detail-assign')?.addEventListener('click',async()=>{const saved=await act('assign',{id:ticket.id,technicianId:document.querySelector('#detail-tech').value});if(saved){view='tickets';render();}});document.querySelector('#close-ticket')?.addEventListener('click',()=>{if(confirm('Close this ticket? This cancels the active request.'))act('close',{id:ticket.id});});}
 function metrics(jobs){const pending=jobs.filter(x=>!finished(x)),done=jobs.filter(x=>x.status==='completed'),rated=done.filter(x=>x.rating),rating=rated.length?(rated.reduce((sum,x)=>sum+x.rating,0)/rated.length).toFixed(1):'—';return {pending,done,rated,rating};}
 function cards(jobs){const m=metrics(jobs);return `<div class="stats tech-stats"><div class="stat">Assigned tickets<b>${jobs.length}</b></div><div class="stat">Pending tasks<b>${m.pending.length}</b></div><div class="stat">Completed<b>${m.done.length}</b></div><div class="stat">Customer rating<b>${m.rating}</b></div></div><div class="card"><h2>Productivity</h2><div class="productivity"><span style="width:${jobs.length?Math.round(m.done.length/jobs.length*100):0}%"></span></div><p class="muted">${m.done.length} of ${jobs.length} assigned tickets completed. ${m.rated.length} customer rating${m.rated.length===1?'':'s'}.</p></div>`;}
 function technicianDashboard(){const jobs=data.bookings||[],pending=metrics(jobs).pending;app.innerHTML=`<div class="intro"><div><div class="eyebrow">TECHNICIAN DASHBOARD</div><h1>${esc(localUser.name)}</h1><p>Your assigned work and customer ratings.</p></div></div>${cards(jobs)}<section class="card"><h2>Pending tasks</h2>${pending.length?pending.map(x=>`<button class="ticket-row" data-tech-ticket="${x.id}"><span><strong>${esc(svc(x.service).en)}</strong><small>${esc(x.village)} · ${esc(x.id)}</small></span><span class="ticket-status progress">${esc(status(x))}</span></button>`).join(''):'<p class="muted">No pending tasks.</p>'}</section>`;app.querySelectorAll('[data-tech-ticket]').forEach(b=>b.onclick=()=>{selected=b.dataset.techTicket;view='technician-ticket';render();});}
 function ownerMonitor(){const technicians=data.technicians||[];let chosen=sessionStorage.getItem('gramin-monitor-tech')||technicians[0]?.id,person=technicians.find(x=>x.id===chosen)||technicians[0];if(!person){app.innerHTML=`${back('Owner dashboard')}<div class="card"><h1>Technician dashboard</h1><p>No active technicians yet.</p></div>`;bindBack();return;}chosen=person.id;const jobs=(data.bookings||[]).filter(x=>x.technicianId===chosen),m=metrics(jobs);app.innerHTML=`${back('Owner dashboard')}<div class="intro"><div><div class="eyebrow">OWNER · TECHNICIAN MONITOR</div><h1>Technician dashboard</h1><p>Monitor assigned work, completion and customer ratings.</p></div></div><label class="field monitor-picker">Technician<select id="monitor-technician">${technicians.map(x=>`<option value="${x.id}" ${x.id===chosen?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${cards(jobs)}<section class="card"><h2>Assigned tasks</h2>${jobs.length?jobs.map(x=>`<button class="ticket-row" data-monitor-ticket="${x.id}"><span><strong>${esc(svc(x.service).en)}</strong><small>${esc(x.village)} · ${esc(x.id)} · ${esc(date(x.createdAt))}</small></span><span class="ticket-status">${esc(status(x))}</span></button>`).join(''):'<p class="muted">No tickets assigned yet.</p>'}<h3>Customer ratings</h3>${m.rated.length?m.rated.map(x=>`<p>${esc(x.id)} · ${esc(svc(x.service).en)} · ${x.rating} / 5 stars</p>`).join(''):'<p class="muted">No customer ratings yet.</p>'}</section>`;bindBack();document.querySelector('#monitor-technician').onchange=e=>{sessionStorage.setItem('gramin-monitor-tech',e.target.value);ownerMonitor();};app.querySelectorAll('[data-monitor-ticket]').forEach(b=>b.onclick=()=>{selected=b.dataset.monitorTicket;view='ticket-detail';render();});}
 function serviceSettings(){const settings=data.settings,serviceCards=data.services.map(x=>`<div class="service-setting"><strong>${esc(x.en)}</strong><small>${esc(x.detail)}</small></div>`).join('');app.innerHTML=`${back('Owner dashboard')}<div class="intro"><div><div class="eyebrow">OWNER TOOLS</div><h1>Service settings</h1><p>Manage the service areas and charges shown to customers.</p></div></div><section class="card focus-panel"><h2>Services offered</h2><div class="service-settings-grid">${serviceCards}</div><h2>Service areas and fees</h2><form id="focused-service-settings"><label class="field">Service areas · one per line<textarea name="areas" required>${esc(settings.areas.join('\n'))}</textarea></label><div class="fields"><label class="field">Visit fee · ₹<input type="number" name="visitFee" min="0" required value="${settings.visitFee}"></label><label class="field">Travel fee · ₹<input type="number" name="travelFee" min="0" required value="${settings.travelFee}"></label></div><p class="muted">New fees apply to future requests. Existing tickets keep their original fee.</p><button class="primary" type="submit">Save service settings</button></form></section>`;bindBack();document.querySelector('#focused-service-settings').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const saved=await act('settings',{...settings,areas:values.areas.split('\n').map(x=>x.trim()).filter(Boolean),visitFee:Number(values.visitFee),travelFee:Number(values.travelFee)});if(saved)toast('Service settings saved');};}
 function technicians(){const roster=data.technicians||[],pending=(data.accounts||[]).filter(x=>x.role==='technician'&&x.status==='pending');app.innerHTML=`${back('Owner dashboard')}<div class="intro"><div><div class="eyebrow">OWNER TOOLS</div><h1>Technicians</h1><p>Manage your team and review pending applications.</p></div><span class="pill">${roster.length} technicians</span></div><div class="owner-actions"><button class="primary" id="new-technician">+ Add new technician</button><button class="secondary" id="monitor-team">View team performance</button></div><section class="card"><h2>Team roster</h2><div class="roster-grid">${roster.map(person=>{const jobs=(data.bookings||[]).filter(x=>x.technicianId===person.id),m=metrics(jobs);return `<div class="roster-person"><span class="roster-avatar">${esc(person.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(person.name)}</strong><small>${person.skills.map(id=>esc(svc(id)?.en||id)).join(' · ')}</small><small>${jobs.length} assigned · ${m.pending.length} pending · ${m.done.length} done</small></div><button type="button" class="quiet" data-monitor-person="${person.id}">View</button></div>`;}).join('')}</div></section>${pending.length?`<section class="card"><h2>Pending applications <span class="pill">${pending.length}</span></h2>${pending.map(x=>`<div class="roster-person"><div><strong>${esc(x.name)}</strong><small>${esc(x.login)} · ${x.skills.map(esc).join(', ')}</small></div><button class="secondary" data-approve-person="${x.id}">Approve</button></div>`).join('')}</section>`:''}`;bindBack();document.querySelector('#new-technician').onclick=()=>{view='owner-technician-new';render();};document.querySelector('#monitor-team').onclick=()=>{view='owner-monitor';render();};app.querySelectorAll('[data-monitor-person]').forEach(button=>button.onclick=()=>{sessionStorage.setItem('gramin-monitor-tech',button.dataset.monitorPerson);view='owner-monitor';render();});app.querySelectorAll('[data-approve-person]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const response=await fetch('/api/auth/technicians/approve',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+localToken},body:JSON.stringify({userId:button.dataset.approvePerson})}),result=await response.json();if(!response.ok)throw Error(result.error);await load();render();toast('Technician approved');}catch(error){button.disabled=false;toast(error.message);}});}
 function addTechnician(){app.innerHTML=`${back('Technicians','owner-technicians')}<section class="card focus-panel"><div class="eyebrow">OWNER TOOLS</div><h1>Add new technician</h1><p class="muted">Create a technician account and choose the services they can handle.</p><form id="new-technician-form"><label class="field">Full name<input name="name" required maxlength="80" autocomplete="name"></label><label class="field">Email or mobile<input name="login" required autocomplete="username"></label><label class="field">Temporary password<input name="password" type="password" required minlength="6" maxlength="128" autocomplete="new-password"></label><fieldset class="skills"><legend>Service skills</legend>${data.services.map(x=>`<label class="check"><input type="checkbox" name="skills" value="${x.id}">${esc(x.en)}</label>`).join('')}</fieldset><p id="technician-form-error" class="auth-error" role="alert"></p><button class="primary" type="submit">Add technician</button></form></section>`;bindBack();document.querySelector('#new-technician-form').onsubmit=async e=>{e.preventDefault();const form=e.target,values=new FormData(form),skills=values.getAll('skills');if(!skills.length){document.querySelector('#technician-form-error').textContent='Select at least one service skill';return;}const button=form.querySelector('button[type=submit]');button.disabled=true;try{const response=await fetch('/api/auth/technicians',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+localToken},body:JSON.stringify({name:values.get('name'),login:values.get('login'),password:values.get('password'),skills})}),result=await response.json();if(!response.ok)throw Error(result.error);await load();view='owner-technicians';render();toast('Technician added');}catch(error){button.disabled=false;document.querySelector('#technician-form-error').textContent=error.message;}};}
 function admins(){const accounts=(data.accounts||[]).filter(x=>x.role==='admin');app.innerHTML=`${back('Owner dashboard')}<div class="intro"><div><div class="eyebrow">OWNER TOOLS</div><h1>Admins</h1><p>Owner access and new Admin accounts.</p></div><span class="pill">${accounts.length} added</span></div><section class="card focus-panel"><h2>Add new Admin</h2><form id="focused-admin-form"><label class="field">Full name<input name="name" required maxlength="80"></label><label class="field">Email or mobile<input name="login" required></label><label class="field">Temporary password<input name="password" type="password" required minlength="6" maxlength="128"></label><p id="focused-admin-error" class="auth-error" role="alert"></p><button class="primary" type="submit">Create Admin</button></form></section><section class="card focus-panel"><h2>Created Admin accounts</h2>${accounts.length?accounts.map(x=>`<p>${esc(x.name)} · ${esc(x.login)}</p>`).join(''):'<p class="muted">No additional Admin accounts yet.</p>'}</section>`;bindBack();document.querySelector('#focused-admin-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');button.disabled=true;try{const response=await fetch('/api/auth/admins',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+localToken},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),result=await response.json();if(!response.ok)throw Error(result.error);await load();render();toast('Admin account created');}catch(error){button.disabled=false;document.querySelector('#focused-admin-error').textContent=error.message;}};}
 function ownerHome(){
  const jobs=data.bookings||[],pending=jobs.filter(x=>!finished(x)),unassigned=pending.filter(x=>!x.technicianId),completed=jobs.filter(x=>x.status==='completed'),cancelled=jobs.filter(x=>['cancelled','declined'].includes(x.status)),total=jobs.length||1;
  const servicesRows=data.services.map(service=>{const count=jobs.filter(x=>x.service===service.id).length;return `<div class="dashboard-bar"><span>${esc(service.en)}</span><div><i style="width:${Math.round(count/total*100)}%"></i></div><b>${count}</b></div>`;}).join('');
  const issueRows=jobs.slice(0,5).map(ticket=>`<button type="button" class="owner-issue" data-owner-ticket="${esc(ticket.id)}"><span><strong>${esc(svc(ticket.service).en)} · ${esc(ticket.id)}</strong><small>${esc(ticket.name)} · ${esc(ticket.village)}</small><span class="owner-issue-text">${esc(ticket.issue)}</span></span><span class="ticket-status">${esc(status(ticket))}</span></button>`).join('');
  app.innerHTML=`<div class="intro"><div><div class="eyebrow">OWNER DASHBOARD</div><h1>Your service operation</h1><p>Customer issues, bookings and team activity at a glance.</p></div><span class="pill">Live local preview</span></div><div class="owner-metrics"><div class="owner-metric"><small>Total tickets</small><strong>${jobs.length}</strong><span>All service requests</span></div><div class="owner-metric warm"><small>Needs assignment</small><strong>${unassigned.length}</strong><span>Ready for dispatch</span></div><div class="owner-metric mint"><small>In progress</small><strong>${pending.length-unassigned.length}</strong><span>Assigned active work</span></div><div class="owner-metric lilac"><small>Completed</small><strong>${completed.length}</strong><span>${cancelled.length} cancelled or declined</span></div></div><div class="layout owner-dashboard-grid"><section class="card"><div class="row"><h2>Services in demand</h2><span class="pill">${jobs.length} tickets</span></div><div class="dashboard-bars">${servicesRows}</div></section><aside class="card"><h2>Work progress</h2><div class="dashboard-donut" style="--done:${Math.round(completed.length/total*100)}"><span><strong>${Math.round(completed.length/total*100)}%</strong><small>completed</small></span></div><p class="muted">${completed.length} completed from ${jobs.length} total requests.</p></aside></div><section class="card owner-issues-card"><div class="row"><div><div class="eyebrow">CUSTOMER SUPPORT</div><h2>Customer tickets & issues</h2></div><button class="secondary" type="button" data-owner-action="tickets">View all tickets</button></div><p class="muted">Open a request to review its history, assign a technician, or close the ticket.</p><div class="owner-issues">${issueRows||'<p class="muted">No customer tickets yet.</p>'}</div></section><section class="card"><div class="row"><h2>Manage your operation</h2><span class="pill">${data.technicians.length} technicians</span></div><div class="owner-action-grid"><button data-owner-action="technicians"><strong>Technicians</strong><small>Roster, applications and add new</small></button><button data-owner-action="monitor"><strong>Team performance</strong><small>Workload, ratings and productivity</small></button><button data-owner-action="branches"><strong>Service branches</strong><small>Customer branch choices</small></button><button data-owner-action="settings"><strong>Service settings</strong><small>Areas, services and fees</small></button><button data-owner-action="admins"><strong>Admins</strong><small>Manage Owner access</small></button><button data-owner-action="tickets"><strong>Ticket queue</strong><small>Assigned and unassigned tasks</small></button></div></section>`;
  app.querySelectorAll('[data-owner-action]').forEach(button=>button.onclick=()=>{view=button.dataset.ownerAction==='tickets'?'tickets':'owner-'+button.dataset.ownerAction;render();});
  app.querySelectorAll('[data-owner-ticket]').forEach(button=>button.onclick=()=>{selected=button.dataset.ownerTicket;view='ticket-detail';render();});
 }
 const baseRender=render;render=function(){baseRender();if(!localToken||!data)return;if(role==='admin'&&view==='home')ownerHome();else if(role==='admin'&&view==='owner-branches')branches();else if(role==='admin'&&view==='owner-settings')serviceSettings();else if(role==='admin'&&view==='owner-technicians')technicians();else if(role==='admin'&&view==='owner-technician-new')addTechnician();else if(role==='admin'&&view==='owner-admins')admins();else if(role==='admin'&&view==='ticket-detail')detail();else if(role==='admin'&&view==='owner-monitor')ownerMonitor();else if(role==='technician'&&view==='home')technicianDashboard();};
})();
